<script setup>
import {ref} from 'vue';import {Head,Link,router} from '@inertiajs/vue3';
import Feedback from '../Components/Feedback.vue';
const props=defineProps({questions:Object,filters:Object,subjects:Array,counts:Object});
const selected=ref([]),subject=ref(props.filters.subject||''),status=ref(props.filters.status||'needs_practice'),reason=ref(props.filters.reason||''),busy=ref(false);
function filter(){router.get('/progress/notebook',{subject:subject.value||undefined,status:status.value,reason:reason.value||undefined})}
function practice(mode){busy.value=true;router.post('/library/study',{mode,selected_ids:selected.value},{onFinish:()=>busy.value=false})}
</script>
<template><Head title="Second Serving"/><p class="eyebrow">My Progress</p><h1>Second Serving</h1><p>Your missed practice questions and private notes. Assigned exams stay separate.</p><p>{{counts.needs_practice}} need practice · {{counts.recovered}} latest answers correct · {{counts.all}} in your notebook</p><Link href="/progress">← My Progress</Link>
<form class="filterbar panel" @submit.prevent="filter"><label>Subject<select v-model="subject"><option value="">All subjects</option><option v-for="s in subjects" :key="s">{{s}}</option></select></label><label>View<select v-model="status"><option value="needs_practice">Needs practice</option><option value="recovered">Latest answer correct</option><option value="all">All notes and mistakes</option></select></label><label>Reason<select v-model="reason"><option value="">Any reason</option><option value="unknown">Didn't know</option><option value="confused">Confused concepts</option><option value="misread">Misread</option><option value="guessed">Guessed</option></select></label><button>Apply</button></form>
<div v-if="questions.data.length" class="panel row"><label class="check"><input type="checkbox" :checked="selected.length===questions.data.length" @change="selected=$event.target.checked?questions.data.map(q=>q.id):[]">Select this page</label><span>{{selected.length}} selected</span><button :disabled="!selected.length||busy" @click="practice('tutor')">Practice these again</button><button :disabled="!selected.length||busy" @click="practice('memory')">Make a Memory Maki deck</button></div>
<p v-else class="notice">No questions match this view. Try All notes and mistakes, or start a practice round.</p>
<article v-for="q in questions.data" :key="q.id" class="panel"><label class="check"><input type="checkbox" v-model="selected" :value="q.id">{{q.id}} · {{q.subject}} · {{q.topic}}</label><p class="pre">{{q.stem}}</p><p v-if="q.note" class="inset pre">{{q.note}}</p><details><summary>Review answer and edit my note</summary><Feedback :question="q"/></details></article>
<div class="row"><Link v-if="questions.prev_page_url" :href="questions.prev_page_url">Previous</Link><span>Page {{questions.current_page}} / {{questions.last_page}}</span><Link v-if="questions.next_page_url" :href="questions.next_page_url">Next</Link></div></template>
